namespace RaceDay.Api.Models;

public class Organiser { public int OrganiserId { get; set; } public string Name { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public ICollection<RaceEvent> Events { get; set; } = []; }
public class Participant { public int ParticipantId { get; set; } public string Name { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public int Age { get; set; } public string Gender { get; set; } = ""; public ICollection<Enrolment> Enrolments { get; set; } = []; }
public class RaceEvent { public int EventId { get; set; } public int OrganiserId { get; set; } public Organiser? Organiser { get; set; } public string Name { get; set; } = ""; public DateTime EventDate { get; set; } public string Location { get; set; } = ""; public string Description { get; set; } = ""; public decimal DistanceKm { get; set; } public string EventType { get; set; } = "Run"; public ICollection<EventCategory> EventCategories { get; set; } = []; public ICollection<Enrolment> Enrolments { get; set; } = []; }
public class Category { public int CategoryId { get; set; } public string Name { get; set; } = ""; public string Description { get; set; } = ""; public ICollection<EventCategory> EventCategories { get; set; } = []; public ICollection<Enrolment> Enrolments { get; set; } = []; }
public class EventCategory { public int EventId { get; set; } public RaceEvent? Event { get; set; } public int CategoryId { get; set; } public Category? Category { get; set; } }
public class Enrolment { public int EnrolmentId { get; set; } public int ParticipantId { get; set; } public Participant? Participant { get; set; } public int EventId { get; set; } public RaceEvent? Event { get; set; } public int CategoryId { get; set; } public Category? Category { get; set; } public string Status { get; set; } = "Registered"; public DateTime RegistrationDate { get; set; } = DateTime.UtcNow; public TimeSpan? FinishTime { get; set; } public int? FinishPosition { get; set; } }
